import base64,zlib,subprocess,tempfile
blob=''''''
patch=zlib.decompress(base64.b64decode(blob))
with tempfile.NamedTemporaryFile(suffix='.patch',delete=False) as f:
    f.write(patch); name=f.name
subprocess.run(['patch','-p1','--forward','--batch','-i',name],check=True)
print('V96_METROLOGY_PATCH_APPLIED')
